-- A7: run 119 per-SKU COP -> loaded -> marketing(OK) -> GST/discount/contingency -> MRP. SELECT-only.
select json_agg(t) from (select l.sku_id,l.product_id,l.product_name,l.pack_size,l.pack_uom,l.material_cost_per_sku mat,l.direct_labour_cost_per_sku dl,l.production_overhead_cost_per_sku poh,l.quality_control_overhead_cost_per_sku qc,l.materials_stores_overhead_cost_per_sku ms,l.manufacturing_cop_per_sku cop,l.admin_overhead_cost_per_sku adm,l.finance_admin_overhead_cost_per_sku fadm,l.internal_loaded_cost_per_sku loaded,l.internal_loaded_cost_status lstat,p.mrp_ik,p.mrp_ok,p.marketing_expense_cost_per_sku_ok mkt_ok,p.marketing_expense_cost_per_sku_ik mkt_ik,p.pricing_cost_per_sku_ok pc_ok,s.gst_percent,s.ok_discount_percent,s.contingency_percent,s.ok_selling_price,p.pricing_bridge_status_ok from costing.sku_internal_loaded_cost_snapshot l left join costing.sku_pricing_bridge_snapshot p on p.refresh_run_id=l.refresh_run_id and p.sku_id=l.sku_id left join costing.sku_selling_price_bridge_snapshot s on s.refresh_run_id=l.refresh_run_id and s.sku_id=l.sku_id where l.refresh_run_id=119 order by l.sku_id) t;
-- Lineage probe: loaded cost of SKU 2 / 193 across all runs (sheet values 40.6148 / 545.15 match none)
select refresh_run_id, period_start, valuation_date, max(internal_loaded_cost_per_sku) filter (where sku_id=2) s2, max(internal_loaded_cost_per_sku) filter (where sku_id=193) s193 from costing.sku_internal_loaded_cost_snapshot group by 1,2,3 order by 1 desc;
